<template>
  <view class="page">
    <view v-if="loading" class="state">加载中...</view><view v-else-if="error" class="state"><text>{{ error }}</text><button class="primary retry" @tap="load">重试</button></view>
    <view v-else-if="order">
      <view class="card"><view class="row between"><text class="title">订单号 {{ order.orderNo }}</text><text class="status">{{ order.statusText }}</text></view><text class="sub">下单时间 {{ order.createdAt }}</text></view>
      <view class="card"><text class="section-title">商品信息</text><view v-for="item in goods" :key="item.id" class="goods"><image :src="item.image" mode="aspectFill"/><view><text class="name">{{ item.name }}</text><view class="row between"><text class="sub">{{ item.spec }}</text><text>¥{{ item.price }} ×{{ item.quantity }}</text></view></view></view></view>
      <view class="card"><text class="section-title">收货信息</text><text class="line">{{ order.consignee }} {{ order.phone }}</text><text class="line">{{ order.address }}</text></view>
      <view class="card"><view class="row between"><text>商品总额</text><text>¥{{ order.totalAmount }}</text></view><view class="row between"><text class="strong">实付款</text><text class="pay">¥{{ order.payAmount }}</text></view></view>
      <view v-if="order.logisticsCompany && order.logisticsNo" class="card"><text class="section-title">物流信息</text><view class="row between"><text>快递公司</text><text>{{ order.logisticsCompany }}</text></view><view class="row between"><text>运单号</text><view><text>{{ order.logisticsNo }}</text><text class="copy" @tap="copyNo">复制</text></view></view></view>
      <view class="bottom"><button class="button ghost" open-type="contact" :session-from="'order_' + order.orderNo">联系客服</button><button v-if="order.status === 'pending_payment'" class="button ghost" @tap="cancel">取消订单</button><button v-if="order.status === 'pending_payment'" class="button primary" @tap="pay">去支付</button><button v-if="['paid','shipped'].includes(order.status)" class="button ghost" @tap="refund">申请退款</button><button v-if="order.status === 'shipped'" class="button ghost" @tap="logistics">查看物流</button><button v-if="order.status === 'shipped'" class="button primary" @tap="receive">确认收货</button><text v-if="order.status === 'refunding'" class="button ghost note">退款处理中</text><button v-if="order.status === 'completed'" class="button ghost" @tap="afterSale">申请售后</button><button v-if="order.status === 'completed'" class="button primary" @tap="logistics">查看物流</button></view>
    </view>
  </view>
</template>
<script>
import api from '../../common/api.js'
const money = value => Number(value || 0).toFixed(2)
const maskPhone = value => { const text = String(value || ''); return text.length >= 7 ? `${text.slice(0, 3)}****${text.slice(-4)}` : text }
const statusText = (status, autoCancel) => status === 'cancelled' && (autoCancel === 1 || autoCancel === true) ? '超时关闭' : ({ pending_payment: '待付款', paid: '待发货', shipped: '待收货', received: '已收货', completed: '已完成', cancelled: '已取消', refunding: '退款中', refunded: '已退款' })[status] || '未知状态'
export default { data() { return { id: '', backend: 'cloud', loading: true, error: '', order: null, goods: [] } }, onLoad(options) { this.id = options.id ? decodeURIComponent(String(options.id)) : ''; this.backend = options.backend === 'target' ? 'target' : 'cloud'; if (!this.id) { this.loading = false; this.error = '缺少订单参数' } else this.load() }, methods: {
  async load() { this.loading = true; this.error = ''; try { const data = await api.getOrderDetail(this.id, this.backend); const address = data.address || {}; this.order = { id: data.id, orderNo: data.order_no, status: data.status, statusText: statusText(data.status, data.auto_cancel), createdAt: data.created_at || '—', consignee: address.name || '—', phone: maskPhone(address.phone || address.contact), address: [address.province, address.city, address.district, address.detail].filter(Boolean).join('') || '—', totalAmount: money(data.total_amount), payAmount: money(data.pay_amount), logisticsCompany: data.logistics_company || '', logisticsNo: data.logistics_no || '' }; this.goods = (data.items || []).map(item => ({ id: item.id, name: item.product_name || '未命名商品', image: item.product_image || '/static/navigation/sravx-mark.png', spec: item.spec_desc || '默认', quantity: item.quantity || 1, price: money(item.price) })) } catch (error) { this.error = error.message || '加载失败' } finally { this.loading = false } },
  async pay() { try { uni.showLoading({ title: '调起支付...', mask: true }); const params = await api.createPaymentOrder({ orderId: this.order.id, backend: this.backend, description: this.goods[0] && this.goods[0].name || 'Sravx 商品订单' }); if (params.paid) { uni.hideLoading(); uni.showToast({ title: '支付成功', icon: 'success' }); return this.load() } if (!params.timeStamp || !params.nonceStr || !params.package || !params.paySign) throw new Error('支付参数不完整'); uni.hideLoading(); await uni.requestPayment({ timeStamp: params.timeStamp, nonceStr: params.nonceStr, package: params.package, signType: params.signType || 'RSA', paySign: params.paySign }); uni.showToast({ title: '支付成功', icon: 'success' }); this.load() } catch (error) { uni.hideLoading(); const message = error.errMsg || error.message || '支付失败'; uni.showToast({ title: message.includes('requestPayment:fail cancel') ? '已取消支付' : message, icon: 'none' }) } },
  cancel() { uni.showModal({ title: '确认取消', content: '确定要取消该订单吗？', confirmColor: '#0B0D10', success: async ({ confirm }) => { if (!confirm) return; try { await api.cancelOrder(this.order.id, this.backend); uni.showToast({ title: '订单已取消', icon: 'success' }); this.load() } catch (error) { uni.showToast({ title: error.message || '取消失败', icon: 'none' }) } } }) },
  receive() { uni.showModal({ title: '确认收货', content: '确认已收到商品？', confirmColor: '#0B0D10', success: async ({ confirm }) => { if (!confirm) return; try { await api.confirmReceive(this.order.id, this.backend); uni.showToast({ title: '已确认收货', icon: 'success' }); this.load() } catch (error) { uni.showToast({ title: error.message || '操作失败', icon: 'none' }) } } }) },
  refund() { const shipped = this.order.status === 'shipped'; uni.showModal({ title: shipped ? '申请退款' : '确认退款', content: shipped ? '订单已发货，退款需管理员审核。确认申请退款？' : '订单未发货，退款将立即处理。确认退款？', confirmColor: '#0B0D10', success: async ({ confirm }) => { if (!confirm) return; try { const result = await api.applyRefundRequest({ orderId: this.order.id, backend: this.backend, reason: shipped ? '已发货订单退款' : '未发货自动退款', refundType: 'refund_only' }); if (result && result.autoApproved) await api.refundOrder({ orderId: this.order.id, reason: '未发货自动退款' }); uni.showToast({ title: result && result.autoApproved ? '退款申请已提交' : '已提交审核', icon: 'success' }); this.load() } catch (error) { uni.showToast({ title: error.message || '申请失败', icon: 'none' }) } } }) },
  logistics() { uni.navigateTo({ url: `/pages/order-logistics/index?orderId=${this.order.id}&orderNo=${encodeURIComponent(this.order.orderNo || '')}` }) }, afterSale() { uni.navigateTo({ url: `/pages/order-after-sale/index?orderId=${this.order.id}&type=aftersale` }) }, copyNo() { uni.setClipboardData({ data: this.order.logisticsNo, success: () => uni.showToast({ title: '已复制', icon: 'success' }) }) }
} }
</script>
<style>
.page{min-height:100vh;padding:10px 10px 100px;box-sizing:border-box;background:#F4F6F8;color:#0B0D10}.state{padding:80px 20px;text-align:center;color:#636366}.retry{margin-top:18px}.card{margin-bottom:10px;padding:13px;border-radius:8px;background:#fff}.row{display:flex;align-items:center;gap:8px}.between{justify-content:space-between}.title,.section-title,.name{font-size:14px;font-weight:650}.section-title{display:block;margin-bottom:12px}.status,.pay{color:#0B0D10;font-weight:650}.sub{display:block;margin-top:7px;color:#8e8e93;font-size:11px}.goods{display:flex}.goods image{width:70px;height:70px;border-radius:6px;background:#f0f0f0}.goods>view{display:flex;flex:1;margin-left:10px;flex-direction:column;justify-content:space-between;font-size:12px}.line{display:block;margin-bottom:6px;font-size:12px}.strong{font-weight:650}.copy{margin-left:8px;padding:2px 6px;border:1px solid #0B0D10;border-radius:3px;color:#0B0D10;font-size:11px}.bottom{position:fixed;bottom:0;left:0;right:0;display:flex;flex-wrap:wrap;gap:8px;padding:10px 12px calc(10px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid #eee}.button{flex:1;margin:0;border-radius:20px;font-size:13px;line-height:38px}.button::after{border:0}.ghost{border:1px solid #dcdcdc;background:#fff;color:#666}.primary{background:#0B0D10;color:#fff}.note{text-align:center}
</style>
